namespace purr::web {

namespace {

// A scan the logger was asked for lasts 20 s (docs/intents/ble/sensor.md#which-sensor).
constexpr int SCAN_SECONDS = 20;

void send(const Site& site, const httplib::Request& req, httplib::Response& res, SettingsView view, const Config& cfg)
{
    view.presets = &site.presets;
    view.current = cfg.wheel;
    view.access = cfg.access;
    view.canSave = maySave(cfg, req.remote_addr, view.whyNot);
    view.token = formToken(req, res, "/settings");
    view.overridden = cfg.overridden;
    view.configErrors = cfg.errors;
    view.now = std::time(nullptr);
    view.sensors = loadSensors(site.paths.db);
    Stats st = loadStats(site.paths.db, cal::localDay(view.now), circumferences(cfg));
    view.live = st.live;
    for (auto& p : cfg.profiles.list) {
        const Wheel& w = cfg.wheels.at(p.id);
        auto revs = st.profileRevs.find(p.id);
        long long n = revs == st.profileRevs.end() ? 0 : revs->second;
        view.wheels.push_back({p, w, double(n) * w.circumferenceM() / 1000, p.id == cfg.profiles.current, n > 0});
    }
    view.nextWheel = cfg.profiles.nextId();
    long long requested = modifiedNs(site.paths.scanRequest);
    view.scanning = requested >= 0 && view.now - requested / 1'000'000'000 < SCAN_SECONDS + 5;
    std::string html;
    pages::settings(html, view);
    res.set_header("Cache-Control", "no-store");
    res.set_content(html, "text/html; charset=utf-8");
}

// A form whose save was refused: the page again, with the values as they are.
SettingsView current(const Config& cfg)
{
    SettingsView view;
    view.values = cfg.editable;
    return view;
}

} // namespace

void addSettingsRoutes(const Site& site, httplib::Server& server)
{
    server.Get("/settings", [&](const httplib::Request& req, httplib::Response& res) {
        Config cfg = site.config();
        SettingsView view = current(cfg);
        view.saved = req.has_param("saved");
        view.wasReset = req.has_param("reset");
        view.wheelSaved = req.get_param_value("wheel_saved");
        view.wheelError = req.get_param_value("wheel_error");
        send(site, req, res, std::move(view), cfg);
    });
    server.Post("/settings", [&](const httplib::Request& req, httplib::Response& res) {
        Config cfg = site.config();
        SettingsView view;
        view.values = editableFromForm(req, cfg.editable);
        if (!authorised(req, res, cfg, view.problems))
            return send(site, req, res, std::move(view), cfg);
        view.problems = validate(view.values);
        if (!view.problems.empty()) {
            res.status = 400;
            return send(site, req, res, std::move(view), cfg);
        }
        ensureProfiles(site); // the wheel leaves settings.conf: profile 1 keeps it
        saveOverrides(view.values, site.paths.overrides);
        std::println("settings saved from {}", req.remote_addr);
        res.set_redirect("/settings?saved=1", 303);
    });
    server.Post("/settings/scan", [&](const httplib::Request& req, httplib::Response& res) {
        Config cfg = site.config();
        SettingsView view = current(cfg);
        if (!authorised(req, res, cfg, view.problems))
            return send(site, req, res, std::move(view), cfg);
        std::ofstream(site.paths.scanRequest, std::ios::trunc) << std::time(nullptr) << "\n";
        std::println("scan requested from {}", req.remote_addr);
        res.set_redirect("/settings#sensor", 303);
    });
    server.Post("/settings/reset", [&](const httplib::Request& req, httplib::Response& res) {
        Config cfg = site.config();
        SettingsView view = current(cfg);
        if (!authorised(req, res, cfg, view.problems))
            return send(site, req, res, std::move(view), cfg);
        std::remove(site.paths.overrides.c_str());
        std::println("settings reset from {}", req.remote_addr);
        res.set_redirect("/settings?reset=1", 303);
    });
}

} // namespace purr::web
